"use server"
import { User } from "../lib/models"
import { Post } from "../lib/models"
import { connectdb } from "../lib/db"
import revalidatePath from "next"
export default async function Getpost(username: string){
    try{
    await connectdb()
const finduser =await User.findOne({userId: username})
if(!finduser){
return {success: false,error:"user not found"}
}
const findposts=await Post.find({author:finduser._id})
.sort({createdAt: -1})
.lean()

return{
    success:true,
    data: JSON.parse(JSON.stringify({findposts}))
}
    }catch(error){
        console.error(error)
    }
    return {success:false,error: "error while getting psot "}

}

export async function Crpost(data:{title: string,content: string,name:string}){
    try{
await connectdb()
const finduser =await User.findOne({userId:data.name})
if(!finduser){
    return {success:false,error:"user name not found"}
}
const crtpost=await Post.create({
    title: data.title,
    content: data.content,
    author:finduser._id
})
revalidatePath("/")
return {success: true,
    Post: JSON.parse(JSON.stringify({crtpost}))
}
    }catch(error){
        console.error(error)
    }
    return {success: false,error:" failed to post "}
}